const e=JSON.parse('[{"id":"111_111010_001","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於法律與命令的區別，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"法律係由立法機關制定，而命令則由各機關訂定","imageUrl":null},{"key":"B","text":"通則為法律，細則為命令","imageUrl":null},{"key":"C","text":"法律與命令，均需經過總統公布後生效","imageUrl":null},{"key":"D","text":"以命令限制人民之權利義務，應有法律授權","imageUrl":null}],"correctAnswer":"C","explanation":"依中央法規標準法，法律需經總統公布，而命令係由各機關發布，不一定需經總統公布。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_002","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依地方制度法規定，委辦規則與法律牴觸者無效。此為何種行政法基本原則之展現？","tableData":null,"images":[],"options":[{"key":"A","text":"法律明確性原則","imageUrl":null},{"key":"B","text":"法律保留原則","imageUrl":null},{"key":"C","text":"法律優位原則","imageUrl":null},{"key":"D","text":"法律安定性原則","imageUrl":null}],"correctAnswer":"C","explanation":"法律優位原則指下位階規範不得牴觸上位階規範，故委辦規則不得與法律牴觸。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_003","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列何者為憲法明文規定的基本權利？","tableData":null,"images":[],"options":[{"key":"A","text":"性行為之自主決定","imageUrl":null},{"key":"B","text":"非現役軍人不受軍事審判","imageUrl":null},{"key":"C","text":"姓名權","imageUrl":null},{"key":"D","text":"婚姻自由","imageUrl":null}],"correctAnswer":"B","explanation":"憲法第9條明確規定「人民除現役軍人外，不受軍事審判」，屬憲法本文明定之基本權利。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_004","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於法律優位原則，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"行政命令牴觸憲法時，行政命令無效","imageUrl":null},{"key":"B","text":"行政命令牴觸法律時，行政命令無效","imageUrl":null},{"key":"C","text":"法律牴觸憲法時，法律無效","imageUrl":null},{"key":"D","text":"法律牴觸國際法時，法律無效","imageUrl":null}],"correctAnswer":"D","explanation":"法律優位原則主要探討國內法階層體系，法律牴觸國際法在法律優位原則中並非必然無效。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_005","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"人民因犯罪嫌疑被逮捕拘禁時，其逮捕拘禁機關應將逮捕拘禁原因，以書面告知本人及其本人指定之親友，並至遲於 24 小時內移送該管法院審問。此為下列那一種憲法原則之內涵？","tableData":null,"images":[],"options":[{"key":"A","text":"罪刑法定原則","imageUrl":null},{"key":"B","text":"正當法律程序原則","imageUrl":null},{"key":"C","text":"法律保留原則","imageUrl":null},{"key":"D","text":"法律明確性原則","imageUrl":null}],"correctAnswer":"B","explanation":"憲法第8條關於人身自由保障之程序規定，屬於保障人民基本權利之正當法律程序。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_006","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"當法律規範有漏洞時，可以運用法律補充之方法使其完全。下列何者非屬法律補充之方法？","tableData":null,"images":[],"options":[{"key":"A","text":"類推適用","imageUrl":null},{"key":"B","text":"文義解釋","imageUrl":null},{"key":"C","text":"目的限縮","imageUrl":null},{"key":"D","text":"法律續造","imageUrl":null}],"correctAnswer":"B","explanation":"文義解釋屬於法律解釋方法，係針對法文內容之解釋，而非於法律有漏洞時進行補充。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_007","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"某法律規定：「本法自公布日施行。」若總統於民國 110 年 6 月 1 日公布該法，則該法應於何日生效？","tableData":null,"images":[],"options":[{"key":"A","text":"6 月 1 日","imageUrl":null},{"key":"B","text":"6 月 2 日","imageUrl":null},{"key":"C","text":"6 月 3 日","imageUrl":null},{"key":"D","text":"6 月 4 日","imageUrl":null}],"correctAnswer":"C","explanation":"依中央法規標準法，自公布之日起算至第三日起發生效力。6月1日加兩日為6月3日。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_008","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於我國現行中央政府體制，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"總統對行政院院長有人事任免權","imageUrl":null},{"key":"B","text":"修憲後因立法院喪失對行政院院長的同意權，行政院不再對立法院負責","imageUrl":null},{"key":"C","text":"總統享有被動的國會解散權","imageUrl":null},{"key":"D","text":"我國中央政府體制既不是總統制，也不是內閣制","imageUrl":null}],"correctAnswer":"B","explanation":"雖然立法院喪失閣揆同意權，但行政院依憲法增修條文規定，仍須對立法院負責。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_009","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於公法與私法之區別，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"救濟之方式不同，公法適用行政爭訟，私法則適用民事訴訟","imageUrl":null},{"key":"B","text":"強制執行之依據不同，公法適用行政執行法與行政訴訟法，私法適用強制執行法","imageUrl":null},{"key":"C","text":"損害賠償管道不同，公法適用國家賠償法，私法適用民法","imageUrl":null},{"key":"D","text":"勞動基準法之規範客體為私法上僱傭關係，故屬純粹的私法","imageUrl":null}],"correctAnswer":"D","explanation":"勞動基準法雖規範私法僱傭關係，但具有強制性之公法監督色彩，屬社會法而非純粹私法。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_010","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列何者非屬我國憲法或憲法增修條文賦予大法官之職權？","tableData":null,"images":[],"options":[{"key":"A","text":"解釋憲法","imageUrl":null},{"key":"B","text":"統一解釋法律及命令","imageUrl":null},{"key":"C","text":"審理總統、副總統之罷免","imageUrl":null},{"key":"D","text":"審理政黨違憲之解散","imageUrl":null}],"correctAnswer":"C","explanation":"總統及副總統之罷免由立法院提出，由選民投票決定，並非由司法院大法官審理。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_011","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於刑法第 19 條第 3 項之規定，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"學理上稱之為原因自由行為","imageUrl":null},{"key":"B","text":"本項須行為人在實際實行犯罪時具備完全行為責任能力狀況","imageUrl":null},{"key":"C","text":"現行立法模式，在學理上有稱為例外模式","imageUrl":null},{"key":"D","text":"本項須行為人因故意或過失自行招致無責任能力或限制責任能力狀況","imageUrl":null}],"correctAnswer":"B","explanation":"原因自由行為係指行為人在實行犯罪時處於責任能力缺失狀態，而非具備完全責任能力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_012","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列何者是憲法最高性的直接展現？","tableData":null,"images":[],"options":[{"key":"A","text":"行政院之施政不得牴觸立法院三讀通過，總統公布之法律","imageUrl":null},{"key":"B","text":"法院之判決，不得不適用法規或適用不當","imageUrl":null},{"key":"C","text":"立法院通過之法律，不得牴觸憲法","imageUrl":null},{"key":"D","text":"行政機關之管轄權，不得違反其組織法規，非依法規不得設定或變更","imageUrl":null}],"correctAnswer":"C","explanation":"憲法第171條規定法律與憲法牴觸者無效，此即憲法最高性之直接體現。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_013","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依司法院大法官解釋，有關自由民主憲政秩序，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"係指憲法中具有本質之重要性而為規範秩序存立之基礎者","imageUrl":null},{"key":"B","text":"憲法增修條文如與憲法中具有本質重要性之規範相衝突，依後法優於前法之原則，增修條文之效力優先","imageUrl":null},{"key":"C","text":"其內涵包括憲法規定之民主共和國原則與國民主權原則","imageUrl":null},{"key":"D","text":"凡憲法設置之機關，均有遵守自由民主憲政秩序之義務","imageUrl":null}],"correctAnswer":"B","explanation":"憲法中具有本質重要性之規範具備修憲限界，增修條文若與其衝突仍屬無效。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_014","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依憲法及公民投票法規定，有關我國公民投票制度，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"是憲法上依法行政原則的實現","imageUrl":null},{"key":"B","text":"因為是對事、而非對人的投票，所以普通、平等、直接之投票方法不適用","imageUrl":null},{"key":"C","text":"現行制度不只有全國性，也有地方性之公民投票","imageUrl":null},{"key":"D","text":"為確實監督國家政策之落實，得針對預算與人事事項提案發起公民投票","imageUrl":null}],"correctAnswer":"C","explanation":"公民投票法明定公民投票分為全國性及地方性公民投票，保障人民直接民權之行使。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_015","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"有關比例原則之敘述，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"須採取之方法應有助於目的之達成","imageUrl":null},{"key":"B","text":"多種同樣達成目的之方法中，須採取對人民權益損害最少者","imageUrl":null},{"key":"C","text":"須採取之方法所造成之損害不得與欲達成目的之利益顯失均衡","imageUrl":null},{"key":"D","text":"一行為違反數行政法上義務，應採取最輕之處罰規定","imageUrl":null}],"correctAnswer":"D","explanation":"比例原則包含適當性、必要性及衡量性，與一行為違反數義務應採何種處罰數無關。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_016","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列事項，何者不適用我國行政程序法之程序規定？","tableData":null,"images":[],"options":[{"key":"A","text":"外交部與外國之建交行為","imageUrl":null},{"key":"B","text":"撤銷進出口廠商營業登記之行為","imageUrl":null},{"key":"C","text":"廢止土地徵收之行為","imageUrl":null},{"key":"D","text":"再生能源發電設備生產電能躉購費率之審定行為","imageUrl":null}],"correctAnswer":"A","explanation":"依行政程序法第3條規定，外交及軍事等高度政治性行為不適用該法之程序規定。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_017","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於執行上級命令之行為不罰之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"明知上級公務員之命令為違法而執行之，不得阻卻違法","imageUrl":null},{"key":"B","text":"以下達之命令為下級公務員之職務範圍內，始得主張阻卻違法","imageUrl":null},{"key":"C","text":"下級公務員執行不符法定程式之命令，亦得阻卻違法","imageUrl":null},{"key":"D","text":"命令之形式雖不以書面為限，但仍以具備法定程式為必要","imageUrl":null}],"correctAnswer":"C","explanation":"依刑法第21條，執行上級命令需具備法定程式始能阻卻違法，程式不符則不得免責。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_018","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"人民申請換發汽車行車執照，卻遭公路監理機關以違規罰鍰尚未繳清為由，拒絕換發行車執照。此舉可能違反下列何種行政上之一般法律原則？","tableData":null,"images":[],"options":[{"key":"A","text":"不當聯結禁止原則","imageUrl":null},{"key":"B","text":"比例原則","imageUrl":null},{"key":"C","text":"誠實信用原則","imageUrl":null},{"key":"D","text":"信賴保護原則","imageUrl":null}],"correctAnswer":"A","explanation":"以繳清罰鍰作為換發執照的前提，與行政目的無正當合理關聯，違反不當聯結禁止原則。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_019","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"有關損失補償之敘述，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"因公益而特別犧牲財產上之利益，國家應依法律規定辦理補償","imageUrl":null},{"key":"B","text":"損失補償是針對國家的合法行為而干預人民之財產權所生之填補措施","imageUrl":null},{"key":"C","text":"現行法下，行政徵收不以公用之目的為限","imageUrl":null},{"key":"D","text":"基於平等原則，只要國家對財產權有所限制，即應給予補償","imageUrl":null}],"correctAnswer":"D","explanation":"補償須以「特別犧牲」為前提，並非所有對財產權之限制皆須給予金錢補償。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_020","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"有關公共設施國家賠償責任的敘述，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"須賠償義務機關有故意或過失，始成立國家賠償責任","imageUrl":null},{"key":"B","text":"公共設施委託民間團體管理，因管理欠缺導致人民人身自由或財產受有損害，國家亦負賠償責任","imageUrl":null},{"key":"C","text":"於開放山域的自然公物，經管理機關對公物為適當的警告或標示，人民仍從事冒險或具危險性活動而受有損害，國家不負賠償責任","imageUrl":null},{"key":"D","text":"建築中的公共設施未開放公用，即非屬公共設施","imageUrl":null}],"correctAnswer":"A","explanation":"國家賠償法第3條對公共設施缺陷採無過失責任，不以機關有故意過失為必要。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_021","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於民事訴訟上當事人能力之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"當事人能力為訴訟成立要件之一，若當事人欠缺當事人能力，法院應逕行以訴不合法裁定駁回其訴","imageUrl":null},{"key":"B","text":"非法人團體因不具權利能力，因此不具有當事人能力","imageUrl":null},{"key":"C","text":"無當事人能力人所為之訴訟行為，其效力得經取得能力之人承認而治癒","imageUrl":null},{"key":"D","text":"當事人於訴訟中死亡時，法院應即以當事人能力有欠缺而裁定駁回其訴","imageUrl":null}],"correctAnswer":"C","explanation":"當事人能力之欠缺，性質上屬可補正事項，經取得能力之人承認後可使行為發生效力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_022","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於行政罰的敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"違反行政法上義務之行為，以處罰故意為原則，過失行為之處罰以法律有明文規定為限","imageUrl":null},{"key":"B","text":"滿十四歲以上，未滿十八歲人之行為，得減輕處罰","imageUrl":null},{"key":"C","text":"不得因不知法規而免除行政處罰責任","imageUrl":null},{"key":"D","text":"違反行政法上義務之行為非出於故意或過失者，不予處罰","imageUrl":null}],"correctAnswer":"A","explanation":"依行政罰法第7條，違反行政法上義務不論故意或過失皆應處罰，並非過失處罰需明文規定。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_023","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列行政訴訟法所定之訴訟種類，何者非以行政處分為程序標的？","tableData":null,"images":[],"options":[{"key":"A","text":"撤銷訴訟","imageUrl":null},{"key":"B","text":"申請遭否准之訴訟","imageUrl":null},{"key":"C","text":"怠為處分訴訟","imageUrl":null},{"key":"D","text":"一般給付訴訟","imageUrl":null}],"correctAnswer":"D","explanation":"一般給付訴訟係針對行政處分以外之財產給付或事實行為給付，不以行政處分為標的。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_024","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列有關訴願要件之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"除行政處分違法外，行政處分不當亦得提起訴願","imageUrl":null},{"key":"B","text":"訴願的對象尚包括消極的不作為","imageUrl":null},{"key":"C","text":"一律以原處分機關為受理訴願機關","imageUrl":null},{"key":"D","text":"須以權利或法律上利益遭受侵害為前提","imageUrl":null}],"correctAnswer":"C","explanation":"訴願通常向原處分機關之上級機關提起，並非由原處分機關受理。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_025","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列事件何者為人民不服時可提起訴願的標的？","tableData":null,"images":[],"options":[{"key":"A","text":"稅捐稽徵機關對業者實施實地查核之行為","imageUrl":null},{"key":"B","text":"甲機關聘僱臨時人員所生薪資給付不足之爭議","imageUrl":null},{"key":"C","text":"丙所有之土地被乙機關徵收而對徵收價格不服之爭議","imageUrl":null},{"key":"D","text":"丁警員執行勤務不慎駕車撞傷人民戊所生的糾紛","imageUrl":null}],"correctAnswer":"C","explanation":"徵收補償價格之核定屬於行政處分，人民若有不服可提起訴願進行救濟。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_026","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲夫乙妻結婚多年，無子女。甲尚有祖父丙、祖母丁。甲死亡時，丁依法辦理拋棄繼承。乙之應繼分為多少？","tableData":null,"images":[],"options":[{"key":"A","text":"2/3","imageUrl":null},{"key":"B","text":"1/2","imageUrl":null},{"key":"C","text":"1/3","imageUrl":null},{"key":"D","text":"1/4","imageUrl":null}],"correctAnswer":"A","explanation":"配偶與第三順位繼承人(祖父母)同為繼承時，其應繼分為遺產三分之二。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_027","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於民事訴訟上和解，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"土地疆界糾紛之訴訟，得成立訴訟上和解","imageUrl":null},{"key":"B","text":"法院調解成立者，與訴訟上和解有同一之效力","imageUrl":null},{"key":"C","text":"當事人就未聲明之事項成立和解者，不得為執行名義","imageUrl":null},{"key":"D","text":"當事人於和解之意思已甚接近，得聲請法院於當事人表明之範圍內，定和解方案，於法院將和解方案送達兩造時，視為和解成立","imageUrl":null}],"correctAnswer":"C","explanation":"民事訴訟上和解，縱使包含未聲明之事項，成立後仍具有與確定判決同一之執行效力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_028","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"違反行政法上義務，得予行政處罰之法源依據，下列何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"財政部函釋","imageUrl":null},{"key":"B","text":"法律明文授權訂定之法規命令","imageUrl":null},{"key":"C","text":"法律","imageUrl":null},{"key":"D","text":"地方自治條例","imageUrl":null}],"correctAnswer":"A","explanation":"行政機關之函釋僅屬解釋性規定，不得作為設定處罰義務之直接法律依據。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_029","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於民事訴訟法上公開審理、言詞審理及直接審理原則之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"言詞辯論，應由訴訟代理人以言詞聲明當事人與關係人人數，以及相關證據資料為其程序之開始","imageUrl":null},{"key":"B","text":"當事人應就訴訟關係，為事實上之陳述，其訴訟代理人應就訴訟關係，為法律上之陳述。兩者相異者，以訴訟代理人之陳述為準","imageUrl":null},{"key":"C","text":"法官非參與為判決基礎之辯論者，不得參與判決","imageUrl":null},{"key":"D","text":"原告提出之攻擊或防禦方法，涉及被告之營業秘密者，僅得由法院以職權逕行裁定為審理不公開與判決不公開","imageUrl":null}],"correctAnswer":"C","explanation":"民事訴訟法明定，參與判決之法官必須是參與該案件言詞辯論之法官，此為直接審理原則。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_030","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列有關訊問刑事被告應告知事項之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"被告所犯罪名經告知後，如有變更，不必再告知","imageUrl":null},{"key":"B","text":"被告犯想像競合犯裁判上一罪之案件，只要告知重罪罪名即可","imageUrl":null},{"key":"C","text":"告知得選任辯護人","imageUrl":null},{"key":"D","text":"被告得保持緘默，亦得說謊","imageUrl":null}],"correctAnswer":"C","explanation":"依刑事訴訟法第95條，訊問被告應告知得選任辯護人，以保障被告之防禦權。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_031","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲將其位於臺中之房屋借給好友乙 1 年，係因乙獲臺中之 A 公司聘用，然而乙須通過試用期 3 個月。甲與乙約定：若 3 個月後乙未通過試用，該房屋之使用借貸失其效力。若乙 3 個月後不幸未通過試用，關於該屋之借貸，發生何種效力？","tableData":null,"images":[],"options":[{"key":"A","text":"解除條件成就","imageUrl":null},{"key":"B","text":"停止條件成就","imageUrl":null},{"key":"C","text":"終期屆至","imageUrl":null},{"key":"D","text":"始期屆至","imageUrl":null}],"correctAnswer":"A","explanation":"約定法律行為於條件成就時失其效力者，該條件為解除條件；乙未過試用即條件成就。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_032","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於民法所規定物之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"汽車之輪胎，為動產","imageUrl":null},{"key":"B","text":"土地上之行道樹，為獨立不動產","imageUrl":null},{"key":"C","text":"柴犬為動產","imageUrl":null},{"key":"D","text":"臨時敷設之輕便軌道，為動產","imageUrl":null}],"correctAnswer":"B","explanation":"土地上之樹木屬於土地之成分，並非獨立之不動產。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_033","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲欲開設文創商場，委託乙完成該商場之室內裝潢。甲、乙間訂立何種契約？","tableData":null,"images":[],"options":[{"key":"A","text":"承攬契約","imageUrl":null},{"key":"B","text":"買賣契約","imageUrl":null},{"key":"C","text":"委任契約","imageUrl":null},{"key":"D","text":"僱傭契約","imageUrl":null}],"correctAnswer":"A","explanation":"以完成一定之工作為契約目的（裝潢工程），屬於民法上之承攬契約。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_034","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲開車闖紅燈，撞死正一邊過馬路一邊滑手機之乙。下列敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"甲得主張乙若專心過馬路，就會看到甲的車，故乙對損害之發生與有過失，甲無須賠償","imageUrl":null},{"key":"B","text":"如果甲受僱於丙公司，負責送貨，甲於送貨途中撞死乙，則乙之配偶丁得向丙求償","imageUrl":null},{"key":"C","text":"乙之配偶丁安葬乙後，得向甲請求賠償喪葬費","imageUrl":null},{"key":"D","text":"乙之配偶丁得向甲請求慰撫金","imageUrl":null}],"correctAnswer":"A","explanation":"與有過失僅能減輕賠償金額，不能使行為人完全無須承擔損害賠償責任。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_035","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依民法第 758 條第 1 項規定，不動產物權行為以登記為要件。關於不動產物權行為，下列敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"不動產物權行為以登記為公示手段","imageUrl":null},{"key":"B","text":"不動產物權行為之登記乃宣示登記","imageUrl":null},{"key":"C","text":"不動產物權行為應以書面為之","imageUrl":null},{"key":"D","text":"不動產物權行為不以交付不動產為要件","imageUrl":null}],"correctAnswer":"B","explanation":"我國民法就不動產物權採登記效力主義，登記為權利變更之生效要件，非僅宣示。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_036","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"稱動產質權者，謂債權人對於債務人或第三人移轉占有而供其債權擔保之動產，得就該動產賣得價金優先受償之權。關於質權人之權利，下列敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"質權人得占有質物","imageUrl":null},{"key":"B","text":"質權人得使用質物","imageUrl":null},{"key":"C","text":"質權人得請求無權占有質物者，返還質物於自己","imageUrl":null},{"key":"D","text":"質權人於債權已屆清償期，而未受清償者，得拍賣質物","imageUrl":null}],"correctAnswer":"B","explanation":"質權人雖得占有質物，但除經出質人同意或為保存之必要外，不得擅自使用質物。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_037","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於夫妻共同收養子女，下列敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"夫妻不得收養其直系血親為養子女","imageUrl":null},{"key":"B","text":"夫妻之一方收養他方之親生子女，無須夫妻共同為之","imageUrl":null},{"key":"C","text":"夫妻之一方於婚前有收養子女者，婚後，他方必須收養該名養子女","imageUrl":null},{"key":"D","text":"夫妻之一方不能為意思表示或生死不明已逾 3 年者，他方得單獨收養子女","imageUrl":null}],"correctAnswer":"C","explanation":"法律並無規定婚後配偶必須收養對方婚前已收養之子女，應依各別收養意願定之。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_038","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依民法規定，下列何者無法對受婚生推定之子女提起婚生否認之訴？","tableData":null,"images":[],"options":[{"key":"A","text":"受婚生推定之夫","imageUrl":null},{"key":"B","text":"生母","imageUrl":null},{"key":"C","text":"曾祖父母","imageUrl":null},{"key":"D","text":"該子女本人","imageUrl":null}],"correctAnswer":"C","explanation":"得提起婚生否認之訴的主體僅限於夫妻之一方或子女本人，不包括曾祖父母。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_039","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲立遺囑遺贈其所有之房屋一棟於乙。惟該房屋因丙之過失致毀損滅失。一年後，甲死亡。下列敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"消滅時效已完成，乙不得向丙請求損害賠償","imageUrl":null},{"key":"B","text":"房屋已毀損滅失，不屬於遺產，遺贈無效","imageUrl":null},{"key":"C","text":"推定以甲對丙之損害賠償請求權為遺贈","imageUrl":null},{"key":"D","text":"乙得向甲之繼承人請求債務不履行之損害賠償","imageUrl":null}],"correctAnswer":"C","explanation":"遺贈標的物因第三人過失滅失時，依民法推定以其損害賠償請求權為遺贈標的。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_040","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於偵查中羈押之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"被告犯罪嫌疑重大，檢察官即可羈押","imageUrl":null},{"key":"B","text":"被告涉嫌公然侮辱罪，檢察官亦可羈押","imageUrl":null},{"key":"C","text":"如果被告有反覆實行同一竊盜犯罪之高度可能性，法院可裁定羈押","imageUrl":null},{"key":"D","text":"即使被告有勾串共犯的可能，法院也不可以裁定羈押","imageUrl":null}],"correctAnswer":"C","explanation":"刑事訴訟法明定，若被告有反覆實施特定犯罪(如竊盜)之虞，法院得執行預防性羈押。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_041","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於刑法第 136 條聚眾妨害公務罪構成要件之敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"行為主體限於公務員執行職務之相對人","imageUrl":null},{"key":"B","text":"行為地限於公共場所或公眾得出入之場所","imageUrl":null},{"key":"C","text":"聚集人數須達 5 人以上","imageUrl":null},{"key":"D","text":"首謀及下手實施強暴脅迫，因而致公務員於死或重傷，與傷害致死或傷害致重傷罪，數罪併罰","imageUrl":null}],"correctAnswer":"B","explanation":"刑法第136條明定行為需發生在「公共場所或公眾得出入之場所」，為該罪之構成要件。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_042","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於嚴格證明法則之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"嚴格證明與自由證明並不相同","imageUrl":null},{"key":"B","text":"嚴格證明法則涉及證據能力及有無經合法調查證據之程序","imageUrl":null},{"key":"C","text":"犯罪事實存在之認定需要嚴格之證明","imageUrl":null},{"key":"D","text":"自由證明與自由心證之意義相同","imageUrl":null}],"correctAnswer":"D","explanation":"自由證明指不須受嚴格程序限制之證明方式，與法官自由判斷證據力之自由心證不同。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_043","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"被告以外之人於審判外之書面或言詞陳述，其有無證據能力之判斷，應依何種法則判斷之？","tableData":null,"images":[],"options":[{"key":"A","text":"自白法則","imageUrl":null},{"key":"B","text":"傳聞法則","imageUrl":null},{"key":"C","text":"自由心證法則","imageUrl":null},{"key":"D","text":"意見法則","imageUrl":null}],"correctAnswer":"B","explanation":"被告以外之人於審判外的陳述屬傳聞證據，應依傳聞法則及其例外規定判定證據能力。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_044","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"依刑事訟法第 27 條規定，被告或犯罪嫌疑人得隨時選任辯護人，不包括下列何種情形？","tableData":null,"images":[],"options":[{"key":"A","text":"受司法警察調查時","imageUrl":null},{"key":"B","text":"法院審理準備程序","imageUrl":null},{"key":"C","text":"受上級長官調查時","imageUrl":null},{"key":"D","text":"移送檢察官調查時","imageUrl":null}],"correctAnswer":"C","explanation":"受上級長官調查屬行政內部調查，非刑事訴訟程序，故不適用刑事訴訟法之辯護人規定。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_045","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列關於貪污治罪條例相關法條之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"對於公務員違背職務之行為，要求、期約或收受賄賂或其他不正利益者，構成犯罪","imageUrl":null},{"key":"B","text":"對於公務員職務上之行為，要求、期約或收受賄賂或其他不正利益者，不構成犯罪","imageUrl":null},{"key":"C","text":"對於主管或監督之事務，明知違背法令等規定，直接或間接圖自己或其他私人不法利益，因而獲得利益者，構成犯罪","imageUrl":null},{"key":"D","text":"對於非主管或監督之事務，明知違背法令等規定，利用職權機會或身分圖自己或其他私人不法利益，因而獲得利益者，構成犯罪","imageUrl":null}],"correctAnswer":"B","explanation":"不論是職務上或違背職務之行為，只要公務員要求或收受賄賂，皆構成受賄罪。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_046","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"甲犯侵占罪，尚未被發覺，妻子乙為庇護甲而出面向警方表示係其犯罪，乙是否符合刑法自首要件？","tableData":null,"images":[],"options":[{"key":"A","text":"不符合，因警方並非偵查機關，向警方自首，於法未合","imageUrl":null},{"key":"B","text":"符合，因犯罪既尚未被發覺，乙出面向警方坦承犯行，當屬自首","imageUrl":null},{"key":"C","text":"不符合，因乙非侵占罪行為人，乙自無自首問題","imageUrl":null},{"key":"D","text":"符合，因可以轉換成乙所犯頂替罪之自首","imageUrl":null}],"correctAnswer":"C","explanation":"自首須由真正的犯罪行為人向偵查機關申報犯罪，非行為人出面承認並不符合自首。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_047","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"關於刑法上之故意犯與過失犯，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"行為非出於故意者，即係出於過失","imageUrl":null},{"key":"B","text":"間接故意犯與有認識過失犯之罪質相當","imageUrl":null},{"key":"C","text":"刑法以處罰故意犯為原則，但過失犯情節嚴重者，仍應與故意犯同視","imageUrl":null},{"key":"D","text":"過失犯之處罰以法律有明文者為限","imageUrl":null}],"correctAnswer":"D","explanation":"依刑法第12條規定，行為非出於故意不罰，過失行為則以法律有明文規定處罰者為限。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_048","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"下列有關刑法第 138 條侵害公務上掌管文書物品罪之敘述，何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"甲收到法院寄發之傳票後，將之撕毀，甲成立本罪","imageUrl":null},{"key":"B","text":"甲撕毀警員乙依法制作之談話筆錄，甲成立本罪","imageUrl":null},{"key":"C","text":"甲與警員乙發生拉扯，致乙所穿制服毀損，甲不成立本罪","imageUrl":null},{"key":"D","text":"警員乙將經扣押之物交由該物之所有權人甲暫時保管，甲故意將之毀損，甲成立本罪","imageUrl":null}],"correctAnswer":"A","explanation":"法院傳票送達當事人後，即非屬公務員職務上掌管之文書，撕毀不成立侵害公務文書罪。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_049","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"刑法第 17 條因犯罪致發生一定之結果，而有加重其刑之規定者，如行為人不能預見其發生時，不適用之。依實務見解，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"必須行為人主觀上有預見結果發生","imageUrl":null},{"key":"B","text":"本條在學理上稱為加重結果犯","imageUrl":null},{"key":"C","text":"必須刑法條文有特別規定才有適用","imageUrl":null},{"key":"D","text":"基礎犯罪與發生結果間須具備因果關係","imageUrl":null}],"correctAnswer":"A","explanation":"加重結果犯要求行為人對加重結果需「客觀上能預見」，而非主觀上已有預見。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"},{"id":"111_111010_050","category":"economics","stageId":"111_111010_503","type":"multiple-choice","difficulty":2,"text":"行政程序法第 3 條第 3 項明列特定事項不適用該法之程序規定，下列何種行為即屬該法所定排除之事項？","tableData":null,"images":[],"options":[{"key":"A","text":"內政部移民署依法禁止本國人出境","imageUrl":null},{"key":"B","text":"高雄市警察局員警依據集會遊行法規定命令群眾立即解散","imageUrl":null},{"key":"C","text":"國防部將部隊連級主官調任為內部單位參謀","imageUrl":null},{"key":"D","text":"私立大學依據該校規定對特定學生為記過處分","imageUrl":null}],"correctAnswer":"C","explanation":"行政程序法第3條規定，軍事機關之人事任免行為不適用該法之程序規定。","points":2,"tags":["111","111010","111年公務人員初等考試","初等考試","初等考試","503","勞工行政","法學大意","測驗題"],"certificationType":"111年公務人員初等考試"}]');export{e as default};
